const animatedSvgMarkup = createAnimatedMarkup(svgMarkup);

export function SecretVisual() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return;
    }

    const svg = container.querySelector<SVGSVGElement>("svg");
    if (!svg) return;

    // Pin the frame-0 picture for as long as this component is mounted. The
    // animation is authored to start and end on exactly this state, so the loop
    // is never entered or left against the raw SVG values -- which is what would
    // otherwise flash the finished result for a frame. Applied only past the
    // reduced-motion guard above, so the no-JS and reduced-motion fallback stays
    // the complete composition.
    svg.classList.add("secret-motion-ready");

    const isRunning = () => svg.classList.contains("secret-motion-active");

    // Drop the class, flush layout, re-add it. That is what guarantees every
    // track restarts at timeline 0 together rather than resuming a stale frame.
    const startFromFrameOne = () => {
      svg.classList.remove("secret-motion-active");
      void svg.getBoundingClientRect();
      svg.classList.add("secret-motion-active");
    };

    // Removing only the active class tears the animations down so no animation
    // work is left running off-screen, while "secret-motion-ready" keeps the
    // frame-0 picture on screen. Stopping and restarting are therefore invisible.
    const stop = () => svg.classList.remove("secret-motion-active");

    if (!("IntersectionObserver" in window)) {
      startFromFrameOne();
      return () => {
        stop();
        svg.classList.remove("secret-motion-ready");
      };
    }

    const observer = new IntersectionObserver(
      (entries) => {
        // A fast scroll can coalesce both thresholds into one delivery, and only
        // the last entry describes where the visual actually is now.
        const entry = entries[entries.length - 1];
        if (!entry) return;
        if (entry.isIntersecting && entry.intersectionRatio >= START_RATIO) {
          if (!isRunning()) startFromFrameOne();
        } else if (!entry.isIntersecting && isRunning()) {
          stop();
        }
      },
      { threshold: [0, START_RATIO] },
    );
    observer.observe(container);

    return () => {
      observer.disconnect();
      stop();
      svg.classList.remove("secret-motion-ready");
    };
  }, []);

  return (
    <div ref={containerRef} className="on-demand-visual secret-visual">
      <div
        role="img"
        aria-label="Beam securely attaches a workspace and makes environment secrets available"
        dangerouslySetInnerHTML={{ __html: animatedSvgMarkup }}
      />
    </div>
  );
}
